7	/**
8	 * Assigns the owner's {@code namesakeCount}: the number of existing owners (before this create)
9	 * sharing the same firstName and lastName, compared case-insensitively.
10	 *
11	 * <p>Runs after {@link BuildOwner} has mapped the request onto the entity and before
12	 * {@link SaveOwner}, within the same write transaction; it counts the owners persisted so far
13	 * (excluding this new, not-yet-saved one), so the value reflects the state immediately before the
14	 * insert.
15	 */
16	public class AssignNamesakeCount {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        String firstName = owner.getFirstName();
20	        String lastName = owner.getLastName();
21	        int count = 0;
22	        for (Owner existing : ownerRepository.findAll()) {
23	            if (equalsIgnoreCase(firstName, existing.getFirstName())
24	                    && equalsIgnoreCase(lastName, existing.getLastName())) {
25	                count++;
26	            }
27	        }
28	        owner.setNamesakeCount(count);
29	    }
30	
31	    private static boolean equalsIgnoreCase(String a, String b) {
32	        return a == null ? b == null : a.equalsIgnoreCase(b);
33	    }
34	}
