3	import java.util.List;
4	import java.util.Locale;
5	import java.util.Set;
6	import java.util.regex.Pattern;
7	
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	
10	/**
11	 * Shared handling of the optional owner {@code email}: when present it must be a syntactically
12	 * valid address, and is stored (and later returned) lower-cased. Absent or blank email is accepted.
13	 *
14	 * <p>Used by both create ({@link ValidateOwnerFields}) and update ({@link ValidateOwner}) so the two
15	 * endpoints treat email identically.
16	 */
17	final class OwnerEmail {
18	
19	    /**
20	     * Practical RFC-5322-ish syntactic check: a non-empty local part, an {@code @}, and a dotted
21	     * domain ending in a letter-only TLD of at least two characters. Rejects values with whitespace
22	     * or a missing {@code @}/domain (e.g. {@code not-an-email}).
23	     */
24	    private static final Pattern EMAIL = Pattern.compile(
25	        "^[\\w!#$%&'*+/=?`{|}~^-]+(?:\\.[\\w!#$%&'*+/=?`{|}~^-]+)*"
26	            + "@(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\\.)+[A-Za-z]{2,}$");
27	
28	    /**
29	     * Disposable email domains that are not accepted: an email on one of these domains is rejected
30	     * (400) even though it is syntactically valid. Compared case-insensitively.
31	     */
32	    private static final Set<String> DISPOSABLE_DOMAINS = Set.of(
33	        "mailinator.com", "tempmail.com", "guerrillamail.com");
34	
35	    private OwnerEmail() {
36	    }
37	
38	    /**
39	     * Validates and normalizes the email on the request in place. When an email is present but not
40	     * syntactically valid, or its domain is on the disposable-domain blocklist, adds {@code "email"}
41	     * to {@code errors} (a 400). When valid, rewrites it lower-cased so persistence and the response
42	     * carry the canonical form. Absent/blank is a no-op.
43	     */
44	    static void normalize(OwnerFieldsDto request, List<String> errors) {
45	        String email = request.getEmail();
46	        if (email == null || email.isBlank()) {
47	            return;
48	        }
49	        if (!EMAIL.matcher(email).matches()) {
50	            errors.add("email");
51	            return;
52	        }
53	        String normalized = email.toLowerCase(Locale.ROOT);
54	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
55	        if (DISPOSABLE_DOMAINS.contains(domain)) {
56	            errors.add("email");
57	            return;
58	        }
59	        request.setEmail(normalized);
60	    }
61	}
