35	
36	    /**
37	     * Derives the owner's {@code ageBand} from {@code birthDate}, computed against the
38	     * {@code registrationDate}: {@code 'MINOR'} when under 18, {@code 'ADULT'} from 18 to 64 and
39	     * {@code 'SENIOR'} at 65 or over. Returns {@code null} when either date is absent, so owners
40	     * without a birthDate map cleanly.
41	     */
42	    default String ageBand(Owner owner) {
43	        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
44	            return null;
45	        }
46	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
47	        if (age < 18) {
48	            return "MINOR";
49	        }
50	        if (age < 65) {
51	            return "ADULT";
52	        }
53	        return "SENIOR";
54	    }
55	
56	    /**
57	     * Derives the owner's {@code identityKey}, the single key all duplicate detection is expressed
58	     * through: {@code '<normalizedTelephone>|<email or empty>|<householdId>'}
59	     * (see {@link org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity}).
60	     */
61	    default String identityKey(Owner owner) {
62	        return org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity
63	                .identityKey(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
64	    }
